From b840c27e0aa431d251f6b6658d24092c00cd54fd Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 21:20:26 +0100
Subject: [PATCH] applets/kickoff: Use Milou.ResultsView for search results

Kickoff showed search results with its own list view and delegates, so
they looked and behaved differently from the same results in KRunner
and Overview. Show them with Milou's shared ResultsView instead.

BUG: 478188
---
 .../kickoff/AbstractKickoffItemDelegate.qml   |  6 +-
 applets/kickoff/FullRepresentation.qml        | 68 +++++++++++--------
 applets/kickoff/KickoffListDelegate.qml       |  6 +-
 applets/kickoff/KickoffListView.qml           | 37 +---------
 applets/kickoff/main.qml                      | 12 ----
 5 files changed, 44 insertions(+), 85 deletions(-)

diff --git a/applets/kickoff/AbstractKickoffItemDelegate.qml b/applets/kickoff/AbstractKickoffItemDelegate.qml
index bc4fcbae6c..eb7a03f2f3 100644
--- a/applets/kickoff/AbstractKickoffItemDelegate.qml
+++ b/applets/kickoff/AbstractKickoffItemDelegate.qml
@@ -43,7 +43,6 @@ T.ItemDelegate {
     property bool isCategoryListItem: false
     property bool removalPlaceholderActive: false
     readonly property bool hasActionList: model && (model.favoriteId !== null || ("hasActionList" in model && model.hasActionList === true))
-    property bool isSearchResult: false

     readonly property bool isSeparator: model && (model.isSeparator === true)
     property int separatorHeight: KickoffSingleton.lineSvg.horLineHeight + (2 * Kirigami.Units.smallSpacing)
@@ -134,7 +133,7 @@ T.ItemDelegate {
             // don't have focus, to prevent the return/enter key from
             // inappropriately activating unfocused items
             // Also block activation while dragging.
-            if ((!root.activeFocus && !root.isSearchResult) || dragHandler.active || touchDragHandler.active) {
+            if (!root.activeFocus || dragHandler.active || touchDragHandler.active) {
                 return;
             }
             root.view.currentIndex = root.index
@@ -251,8 +250,7 @@ T.ItemDelegate {
     PC3.ToolTip.text: {
         if (root.labelTruncated) {
             return model?.display ?? ""
-        } else if (root.descriptionTruncated || (!root.descriptionVisible && (root.isSearchResult
-                                                                              || Plasmoid.configuration.appNameFormat > 1))) {
+        } else if (root.descriptionTruncated || (!root.descriptionVisible && Plasmoid.configuration.appNameFormat > 1)) {
             return description
         }
         return ""
diff --git a/applets/kickoff/FullRepresentation.qml b/applets/kickoff/FullRepresentation.qml
index f3b703155c..c6c4084463 100644
--- a/applets/kickoff/FullRepresentation.qml
+++ b/applets/kickoff/FullRepresentation.qml
@@ -15,9 +15,11 @@ pragma ComponentBehavior: Bound
 import QtQuick
 import QtQuick.Templates as T
 import QtQuick.Layouts
+import org.kde.milou as Milou
 import org.kde.plasma.plasmoid
 import org.kde.plasma.private.kicker as Kicker
 import org.kde.kirigami as Kirigami
+import org.kde.plasma.components as PC3
 import org.kde.plasma.extras as PlasmaExtras

 EmptyPage {
@@ -98,28 +100,18 @@ EmptyPage {

         Component {
             id: searchViewComponent
-            KickoffListView {
-                id: searchView
+            PC3.ScrollView {
+                id: searchScroll
                 objectName: "searchView"
-                mainContentView: true
-                // Forces the function be re-run every time runnerModel.count changes.
-                // This is absolutely necessary to make the search view work reliably.
-                model: kickoff.runnerModel.count ? kickoff.runnerModel.modelForRow(0) : null
-                delegate: KickoffListDelegate {
-                    width: view.availableWidth
-                    isSearchResult: true
-                }
-                section.property: "group"
-                activeFocusOnTab: true
-                Keys.onTabPressed: event => {
-                    kickoff.firstHeaderItem.forceActiveFocus(Qt.TabFocusReason);
-                }
-                Keys.onBacktabPressed: event => {
-                    kickoff.lastHeaderItem.forceActiveFocus(Qt.BacktabFocusReason);
-                }
-                Keys.onUpPressed: event => {
-                    kickoff.searchField.forceActiveFocus(Qt.BacktabFocusReason)
-                }
+                property alias currentIndex: searchView.currentIndex
+
+                // This keeps the minimum applet size the same whether you are
+                // searching or not.
+                implicitWidth: normalPage.implicitWidth
+                implicitHeight: normalPage.implicitHeight
+
+                focus: true
+
                 T.StackView.onStatusChanged: {
                     if (T.StackView.status === T.StackView.Activating || T.StackView.status === T.StackView.Activating) {
                         kickoff.sideBar = null
@@ -127,11 +119,32 @@ EmptyPage {
                     }
                 }

+                contentItem: Milou.ResultsView {
+                    id: searchView
+
+                    readonly property ListView view: searchView
+                    topMargin: Kirigami.Units.smallSpacing
+                    bottomMargin: Kirigami.Units.smallSpacing
+
+                    keyNavigationWraps: false
+                    queryString: kickoff.searchField ? kickoff.searchField.text : ""
+                    onActivated: kickoff.expanded = false
+                    onUpdateQueryString: (text, cursorPosition) => {
+                        kickoff.searchField.text = text
+                        kickoff.searchField.cursorPosition = cursorPosition
+                    }
+
+                    Keys.onUpPressed: event => {
+                        kickoff.searchField.forceActiveFocus(Qt.BacktabFocusReason)
+                    }
+                }
+
                 Loader {
-                    anchors.centerIn: searchView.view
-                    width: searchView.view.width - (Kirigami.Units.gridUnit * 4)
+                    parent: searchScroll
+                    anchors.centerIn: parent
+                    width: searchScroll.width - (Kirigami.Units.gridUnit * 4)

-                    active: searchView.view.count === 0
+                    active: searchView.count === 0 && !searchView.querying
                     visible: active
                     asynchronous: true

@@ -142,12 +155,7 @@ EmptyPage {
                         opacity: 0
                         text: i18nc("@info:status", "No matches")

-                        Connections {
-                            target: kickoff.runnerModel
-                            function onQueryFinished() {
-                                showAnimation.restart()
-                            }
-                        }
+                        Component.onCompleted: showAnimation.restart()

                         NumberAnimation {
                             id: showAnimation
diff --git a/applets/kickoff/KickoffListDelegate.qml b/applets/kickoff/KickoffListDelegate.qml
index 4e3d57fab4..3d8b4d6248 100644
--- a/applets/kickoff/KickoffListDelegate.qml
+++ b/applets/kickoff/KickoffListDelegate.qml
@@ -91,11 +91,7 @@ AbstractKickoffItemDelegate {
                 PC3.Label {
                     id: descriptionLabel
                     Layout.fillWidth: true
-                    visible: {
-                        let isApplicationSearchResult = root.model?.group === "Applications" || root.model?.group === "System Settings"
-                        let isSearchResultWithDescription = root.isSearchResult && (Plasmoid.configuration?.appNameFormat > 1 || !isApplicationSearchResult)
-                        return text.length > 0 && (isSearchResultWithDescription || (text !== label.text && !root.isCategoryListItem && Plasmoid.configuration?.appNameFormat > 1))
-                    }
+                    visible: text.length > 0 && text !== label.text && !root.isCategoryListItem && Plasmoid.configuration?.appNameFormat > 1
                     opacity: 0.75
                     text: root.description
                     textFormat: Text.PlainText
diff --git a/applets/kickoff/KickoffListView.qml b/applets/kickoff/KickoffListView.qml
index 839ea277e8..effb8768e1 100644
--- a/applets/kickoff/KickoffListView.qml
+++ b/applets/kickoff/KickoffListView.qml
@@ -207,15 +207,6 @@ EmptyPage {
             }
         }

-        Connections {
-            target: kickoff.runnerModel
-            enabled: launchMatchTimer.running
-            function onQueryFinished() : void {
-                launchMatchTimer.stop()
-                Qt.callLater(launchMatchTimer.triggered) // callLater to give bindings time to update
-            }
-        }
-
         // Used to block hover events temporarily after using keyboard navigation.
         // If you have one hand on the touch pad or mouse and another hand on the keyboard,
         // it's easy to accidentally reset the highlight/focus position to the mouse position.
@@ -231,22 +222,6 @@ EmptyPage {
             onTriggered: view.movedWithWheel = false
         }

-        Timer {
-            id: launchMatchTimer
-            interval: 750
-            onTriggered: {
-                view.currentItem?.action.trigger();
-                currentItem.forceActiveFocus(Qt.ShortcutFocusReason);
-            }
-        }
-
-        onCurrentItemChanged: {
-            if (launchMatchTimer.running && view.currentItem?.text.toLowerCase().includes(kickoff.runnerModel.query.toLowerCase())) {
-                launchMatchTimer.stop()
-                launchMatchTimer.triggered()
-            }
-        }
-
         function focusCurrentItem(event, focusReason) {
             currentItem.forceActiveFocus(focusReason)
             positionViewAtIndex(currentIndex, ListView.Contain)
@@ -266,7 +241,7 @@ EmptyPage {
             let targetIndex = currentIndex
             const atFirst = currentIndex === 0
             const atLast = currentIndex === count - 1
-            if (count >= 1 || (kickoff.runnerModel.querying && [Qt.Key_Return, Qt.Key_Enter].includes(event.key))) {
+            if (count >= 1) {
                 switch (event.key) {
                     case Qt.Key_Up: if (!atFirst) {
                         decrementCurrentIndex()
@@ -327,14 +302,8 @@ EmptyPage {
                     case Qt.Key_Return:
                         /* Fall through*/
                     case Qt.Key_Enter:
-                        if (launchMatchTimer.running) {
-                            launchMatchTimer.stop()
-                            launchMatchTimer.triggered()
-                        } else if (!kickoff.runnerModel.querying || view.currentItem?.text.toLowerCase().includes(kickoff.runnerModel.query.toLowerCase())) {
-                            launchMatchTimer.triggered()
-                        } else {
-                            launchMatchTimer.start()
-                        }
+                        (currentItem as AbstractKickoffItemDelegate).action.trigger();
+                        currentItem.forceActiveFocus(Qt.ShortcutFocusReason);
                         event.accepted = true;
                         break;
                 }
diff --git a/applets/kickoff/main.qml b/applets/kickoff/main.qml
index 6b6c95dabe..3f09e15298 100644
--- a/applets/kickoff/main.qml
+++ b/applets/kickoff/main.qml
@@ -81,18 +81,6 @@ PlasmoidItem {
         }
     }

-    readonly property Kicker.RunnerModel runnerModel: Kicker.RunnerModel {
-        query: kickoff.searchField ? kickoff.searchField.text : ""
-        onRequestUpdateQuery: query => {
-            if (kickoff.searchField) {
-                kickoff.searchField.text = query;
-            }
-        }
-        appletInterface: kickoff
-        mergeResults: true
-        favoritesModel: kickoff.rootModel.favoritesModel
-    }
-
     readonly property Kicker.ComputerModel computerModel: Kicker.ComputerModel {
         appletInterface: kickoff
         favoritesModel: kickoff.rootModel.favoritesModel
-- 
2.53.0
